R,C=17,30; g=[[0]*C for _ in range(R)]
# exact masks from input, indexed with top-left coordinate
objs=[(4,2,14,['11111','00100','01110','11111','00100']), (8,7,21,['11111','00010','00111','11111','00010']), (3,9,2,['11111','00100','01110','11111','00100']), (1,12,9,['11111','00100','01110','11111','00100'])]
for color,oldr,c,mask in objs:
 for i,row in enumerate(mask):
  for j,v in enumerate(row):
   if v=='1': g[2+i][c+j]=color
assert len(g)==17 and all(len(row)==30 for row in g)
print('\n'.join(' '.join(map(str,row)) for row in g))

